import heapq
from jifunze_lab import lnd


def fee_msat(policy: dict, amount_msat: int) -> int:
    base = int(policy.get("fee_base_msat", 0))
    rate = int(policy.get("fee_rate_milli_msat", 0))
    return base + amount_msat * rate // 1_000_000


def edges_from(graph: dict) -> dict:
    out: dict = {}
    for e in graph["edges"]:
        for a, b, pol in ((e["node1_pub"], e["node2_pub"], e.get("node1_policy")), (e["node2_pub"], e["node1_pub"], e.get("node2_policy"))):
            if pol and not pol.get("disabled"):
                out.setdefault(a, []).append((b, pol))
    return out


def find_route(graph: dict, source: str, target: str, amount_msat: int) -> list[str]:
    adj = edges_from(graph)
    heap = [(0, source, [source])]
    seen = set()
    while heap:
        cost, node, path = heapq.heappop(heap)
        if node == target:
            return path
        if node in seen:
            continue
        seen.add(node)
        for nxt, pol in adj.get(node, []):
            if nxt not in seen:
                hop_fee = 0 if node == source else fee_msat(pol, amount_msat)
                heapq.heappush(heap, (cost + hop_fee, nxt, path + [nxt]))
    return []


alice = lnd("alice")
graph = alice.graph()
dina = lnd("dina").pubkey
names = {n["pub_key"]: n.get("alias") for n in graph["nodes"]}
route = find_route(graph, alice.pubkey, dina, 10_000_000)
print(" -> ".join(names.get(p, p[:8]) for p in route))
